// bn — বাংলা.
//
// A chave é o TEXTO EM PORTUGUÊS, exatamente como aparece no código. O que faltar aqui aparece em
// português, e não como tela vazia.
//
// TOM: **তুমি**, nunca *আপনি*. É a mesma escolha do du, do ты, do tu, do je, do 你, do sen, do kamu
// e do तुम. O bengali tem três níveis (তুই / তুমি / আপনি) e o do meio é o de amigo: আপনি distancia,
// তুই é íntimo demais para um desconhecido. Como no híndi, isso aparece na terminação do verbo:
// "বেছে নাও" e não "বেছে নিন".
//
// VOCABULÁRIO, decidido uma vez: comunidade = কমিউনিটি, canal = চ্যানেল, sala de voz = ভয়েস রুম,
// mensagem = বার্তা, senha = পাসওয়ার্ড, transmissão = স্ট্রিম, lixeira = ট্র্যাশ, tópico = থ্রেড.
// As palavras que o bengali de tecnologia já tomou emprestadas ficam como estão.
//
// A ESCRITA TEM FONTE PRÓPRIA: 'bengali' → Noto Sans Bengali (ver FONTE_DA_ESCRITA em idiomas.ts).

