  'Os números aparecem no alto da lista de canais, para todo mundo, e mudam sozinhos.': 'সংখ্যাগুলো চ্যানেল তালিকার ওপরে সবার জন্য দেখায়, আর নিজে নিজেই বদলায়।',
  'Criar uma sala para cada pessoa que entrar': 'যে ঢুকবে তার জন্য একটি রুম তৈরি করুন',
  'Entre para criar a sua sala': 'নিজের রুম বানাতে ঢুকুন',
  'Limite de pessoas': 'লোকের সীমা',
  'Quantas pessoas cabem (0 = sem limite)': 'কতজন ধরবে (0 = সীমা নেই)',
  'Canal de destaques': 'বাছাই করা বার্তার চ্যানেল',
  'Destaques': 'বাছাই করা',
  'Estrelas necessárias': 'দরকারি তারা',
  'Quando uma mensagem junta estrelas ⭐ suficientes, o Syden a publica no canal de destaques. A estrela de quem escreveu não conta, e apagar a mensagem apaga o destaque.': 'কোনো বার্তা যথেষ্ট ⭐ তারা পেলে Syden সেটি বাছাই করা বার্তার চ্যানেলে প্রকাশ করে। লেখকের নিজের তারা গোনা হয় না, আর বার্তা মুছলে বাছাইটিও মুছে যায়।',
  '🎉 Resultado do sorteio de {premio}: {vencedores}. Parabéns!': '🎉 {premio}-এর লটারির ফল: {vencedores}। অভিনন্দন!',
  '🎉 Sorteio: {premio}! Reaja com 🎉 para participar. O resultado sai em {quando}.': '🎉 লটারি: {premio}! অংশ নিতে 🎉 দিয়ে প্রতিক্রিয়া দিন। ফল প্রকাশ হবে {quando}।',
  'Começar o sorteio': 'লটারি শুরু করুন',
  'Encerrar agora': 'এখনই শেষ করুন',
  'Ganhadores': 'পুরস্কারের সংখ্যা',
  'Ninguém participou.': 'কেউ অংশ নেয়নি।',
  'Novo sorteio': 'নতুন লটারি',
  'O sorteio de {premio} terminou sem participantes.': '{premio}-এর লটারি কোনো অংশগ্রহণকারী ছাড়াই শেষ হয়েছে।',
  'O Syden anuncia o prêmio no canal, e quem quiser participar reage com 🎉. Na hora marcada, ele sorteia entre quem reagiu e publica o resultado.': 'Syden চ্যানেলে পুরস্কার ঘোষণা করে, আর যে অংশ নিতে চায় সে 🎉 দিয়ে প্রতিক্রিয়া দেয়। নির্ধারিত সময়ে প্রতিক্রিয়া দেওয়াদের মধ্য থেকে লটারি করে ফল প্রকাশ করে।',
  'Participantes: {n}': 'অংশগ্রহণকারী: {n}',
  'Prêmio': 'পুরস্কার',
  'Quem ganhou: {nomes}': 'বিজয়ী: {nomes}',
  'Sortear de novo': 'আবার লটারি করুন',
  'Sorteios': 'লটারি',
