  'Termina em {quando}': 'শেষ হবে {quando}',
  'Terminou em {quando}': 'শেষ হয়েছে {quando}',
  'Aniversário': 'জন্মদিন',
  'Aniversários': 'জন্মদিন',
  'Canal dos parabéns': 'শুভেচ্ছার চ্যানেল',
  'Dia': 'দিন',
  'Hoje é aniversário de {pessoa}! 🎉 Parabéns!': 'আজ {pessoa}-এর জন্মদিন! 🎉 শুভ জন্মদিন!',
  'Mês': 'মাস',
  'No dia do aniversário de quem informou a data, o Syden publica os parabéns no canal escolhido. Use {pessoa} no lugar do nome.': 'যিনি তারিখ দিয়েছেন তার জন্মদিনে Syden বেছে নেওয়া চ্যানেলে শুভেচ্ছা প্রকাশ করে। নামের জায়গায় {pessoa} ব্যবহার করুন।',
  'Só o dia e o mês, nunca o ano. As comunidades que avisam aniversários dão os parabéns no dia. É opcional, e dá para apagar quando quiser.': 'শুধু দিন আর মাস, বছর কখনো নয়। যে কমিউনিটিগুলো জন্মদিন জানায়, তারা সেদিন শুভেচ্ছা দেয়। এটি ঐচ্ছিক, যখন খুশি মুছে ফেলা যায়।',
  'Texto dos parabéns': 'শুভেচ্ছার লেখা',
  'Agendar': 'নির্ধারণ করুন',
  'Apagar a mensagem agendada': 'নির্ধারিত বার্তা মুছুন',
  'Canal': 'চ্যানেল',
  'Combinado: lembro você em {tempo}.': 'ঠিক আছে: {tempo} পরে আপনাকে মনে করিয়ে দেব।',
  'Lembrar de mim': 'আমাকে মনে করিয়ে দিন',
  'Lembrar de mim em…': 'আমাকে মনে করিয়ে দিন…',
  'Lembrete': 'রিমাইন্ডার',
  'Lembrete — {autor}: {trecho}': 'রিমাইন্ডার — {autor}: {trecho}',
  'Mensagens agendadas': 'নির্ধারিত বার্তা',
  'Na hora marcada, o Syden publica o texto no canal. Dá para repetir todo dia ou toda semana.': 'নির্ধারিত সময়ে Syden চ্যানেলে লেখাটি প্রকাশ করে। প্রতিদিন বা প্রতি সপ্তাহে পুনরাবৃত্তি করা যায়।',
  'Nova mensagem agendada': 'নতুন নির্ধারিত বার্তা',
  'O que o Syden publica': 'Syden যা প্রকাশ করে',
  'Quando': 'কখন',
  'Repetir': 'পুনরাবৃত্তি',
  'Texto da mensagem agendada': 'নির্ধারিত বার্তার লেখা',
  'Toda semana': 'প্রতি সপ্তাহে',
  'Todo dia': 'প্রতিদিন',
  'Uma vez': 'একবার',
  'Alguém escreve o comando no começo de uma mensagem, como !regras, e o Syden responde no canal com o texto que você cadastrar. Use {pessoa} para o nome de quem pediu e {comunidade} para o nome da comunidade.': 'কেউ বার্তার শুরুতে কমান্ড লেখে, যেমন !regras, আর Syden আপনার দেওয়া লেখা দিয়ে চ্যানেলে উত্তর দেয়। যে চেয়েছে তার নামের জন্য {pessoa} আর কমিউনিটির নামের জন্য {comunidade} ব্যবহার করুন।',
  'Apagar o comando {comando}': '{comando} কমান্ড মুছুন',
