  'Motivo da advertência': 'সতর্কতার কারণ',
  'Seu silêncio em {comunidade} acabou.': '{comunidade}-এ আপনার নীরবতা শেষ হয়েছে।',
  'Silenciar {pessoa} por': '{pessoa}-এর নীরবতার সময়',
  'Silenciar por…': 'নীরবতার সময়…',
  'Tirar o silêncio': 'নীরবতা তুলে নিন',
  'Você está em silêncio em {comunidade} até {hora}.': '{comunidade}-এ আপনি {hora} পর্যন্ত নীরব অবস্থায় আছেন।',
  'Você está em silêncio nesta comunidade até {hora}.': 'এই কমিউনিটিতে আপনি {hora} পর্যন্ত নীরব অবস্থায় আছেন।',
  'Você recebeu uma advertência em {comunidade}: {motivo}': '{comunidade}-এ আপনি একটি সতর্কতা পেয়েছেন: {motivo}',
  'Barrar excesso de mensagens (mais de 5 em 10 segundos)': 'অতিরিক্ত বার্তা আটকান (১০ সেকেন্ডে ৫টির বেশি)',
  'Bloquear links nas mensagens': 'বার্তায় লিংক আটকান',
  'Desligado': 'বন্ধ',
  'Modo lento': 'ধীর মোড',
  'Modo lento de {canal}': '{canal}-এর ধীর মোড',
  'Modo lento: uma mensagem a cada {tempo}.': 'ধীর মোড: প্রতি {tempo}-এ একটি বার্তা।',
  'Palavras proibidas': 'নিষিদ্ধ শব্দ',
  'Quanto tempo cada pessoa espera entre uma mensagem e outra no canal.': 'চ্যানেলে প্রত্যেককে এক বার্তা থেকে আরেক বার্তার মধ্যে কত সময় অপেক্ষা করতে হবে।',
  'Regras': 'নিয়ম',
  'Regras que o Syden aplica sozinho, antes de a mensagem aparecer. Quem administra não passa por elas. A mensagem barrada volta para quem escreveu, com o motivo, e ninguém mais a vê.': 'বার্তা দেখানোর আগে Syden নিজেই যে নিয়মগুলো প্রয়োগ করে। পরিচালকদের জন্য এগুলো খাটে না। আটকানো বার্তা কারণসহ লেখকের কাছে ফিরে যায়, আর কেউ তা দেখে না।',
  'Salvo.': 'সংরক্ষিত।',
  'Uma por linha. Vale a palavra inteira, sem diferença de acento ou de maiúscula: proibir uma palavra não barra outra mais longa que só a contenha.': 'প্রতি লাইনে একটি। পুরো শব্দটি গণ্য হয়, উচ্চারণচিহ্ন বা বড়-ছোট হাতের তফাত ছাড়া: একটি শব্দ নিষিদ্ধ করলে সেটি ধারণ করা দীর্ঘ শব্দ আটকায় না।',
  '{faltam} pontos para o nível {proximo}.': 'লেভেল {proximo}-এ যেতে আরও {faltam} পয়েন্ট।',
  'Adicionar recompensa': 'পুরস্কার যোগ করুন',
  'Cada mensagem vale pontos (uma por minuto), e cada minuto numa sala com mais alguém também. Quem sobe de nível recebe um aviso só para si.': 'প্রতিটি বার্তায় পয়েন্ট মেলে (মিনিটে একটি), আর অন্য কারও সঙ্গে ঘরে থাকা প্রতিটি মিনিটেও। লেভেল বাড়লে শুধু নিজের কাছে একটি বার্তা আসে।',
  'Cargo da recompensa': 'পুরস্কারের ভূমিকা',
  'Crie um cargo acima para usar como recompensa.': 'পুরস্কার হিসেবে ব্যবহার করতে ওপরে একটি ভূমিকা তৈরি করুন।',
  'Escolha o cargo': 'ভূমিকা বেছে নিন',
