  'Recompensas': 'পুরস্কার',
  'Tirar a recompensa do nível {nivel}': 'লেভেল {nivel}-এর পুরস্কার সরান',
  'Você ainda não tem pontos aqui. Converse ou entre numa sala com alguém.': 'এখানে এখনো আপনার কোনো পয়েন্ট নেই। কথা বলুন বা কারও সঙ্গে ঘরে ঢুকুন।',
  'Você chegou ao nível {nivel}!': 'আপনি লেভেল {nivel}-এ পৌঁছেছেন!',
  'Você está em {posicao}º, no nível {nivel}.': 'আপনি {posicao} নম্বরে, লেভেল {nivel}-এ।',
