  'O que você fez a respeito?': 'তুমি এ নিয়ে কী করেছ?',
  'O selo desta comunidade é': 'এই কমিউনিটির ছাপ হলো',
  'O som chega quando você abre esta transmissão.': 'এই স্ট্রিম খুললেই শব্দ চলে আসে।',
  'O survival do Léo': 'Léo-র survival সার্ভার',
  'O Syden já sabe escrever em qualquer uma destas línguas — falta a tradução dos textos. Enquanto ela não chega, o que não estiver traduzido aparece em português, e as letras de cada alfabeto aparecem certas, sem quadradinhos.':
    'Syden এর যেকোনো ভাষাতেই লিখতে পারে — শুধু লেখাগুলোর অনুবাদ বাকি। সেটা না আসা পর্যন্ত যা অনুবাদ হয়নি তা পর্তুগিজে দেখাবে, আর প্রতিটি লিপির অক্ষর ঠিকঠাক দেখাবে, খালি বাক্স ছাড়াই।',
  'O Syden vai ficar fora do ar por uns 10 minutos para uma atualização.': 'একটা হালনাগাদের জন্য Syden মিনিট দশেক বন্ধ থাকবে।',
