  'Para jogos. Manda uma imagem só, a melhor: sobra máquina para o jogo, e quem assiste recebe o que ela é.':
    'খেলার জন্য। একটাই ছবি পাঠায়, সবচেয়ে ভালোটা: খেলার জন্য বেশি শক্তি বাঁচে, আর যে দেখে সে ওটাই পায়।',
