  'Aparece no seu cartão de perfil, para quem fala um idioma achar quem o estuda. É opcional.': "তোমার প্রোফাইল কার্ডে দেখায়, যাতে কোনো ভাষা যে বলে সে যে শিখছে তাকে খুঁজে পায়। এটা ঐচ্ছিক।",
