  'Saúde do servidor': 'সার্ভারের হাল',
  'Se existir uma conta com esse endereço, o link para escolher uma senha nova chegou lá. Ele vale por 1 hora.':
    'ওই ঠিকানায় যদি কোনো অ্যাকাউন্ট থাকে, নতুন পাসওয়ার্ড বাছার লিংক সেখানে পৌঁছে গেছে। সেটা ১ ঘণ্টা কাজ করবে।',
