  'Administradores podem apagar mensagens de qualquer pessoa, gerenciar todos os canais, emojis e sons desta comunidade e remover membros. Só o dono dá e tira esse cargo.': 'অ্যাডমিনরা যে কারো বার্তা মুছতে পারে, এই কমিউনিটির সব চ্যানেল, ইমোজি আর শব্দ সামলাতে পারে, আর সদস্য সরাতে পারে। এই দায়িত্ব শুধু মালিকই দেয় আর ফিরিয়ে নেয়।',
