  'Modificador de voz': 'গলা বদলানো',
  'Muda como os outros ouvem você na chamada. Vale na hora, dá para trocar durante a conversa — e acaba quando você sai da sala: na próxima você entra com a sua voz.': 'কথা বলার সময় অন্যরা তোমাকে কীভাবে শোনে তা বদলে দেয়। সঙ্গে সঙ্গে কাজ করে, কথার মাঝেও বদলাতে পারো — আর ঘর ছাড়লেই শেষ: পরেরবার তুমি নিজের গলা নিয়েই ঢোকো।',
  'Nada faltando: o pacote está completo.': 'কিছুই বাদ নেই: প্যাকেজটা পুরো।',
  'Não deu para salvar o selo.': 'সিলটা রাখা গেল না।',
  'Não deu para tirar o selo.': 'সিলটা খোলা গেল না।',
