  'Notificações na área de trabalho': 'ডেস্কটপে বিজ্ঞপ্তি',
  'O navegador bloqueou as notificações deste site. Libere no cadeado ao lado do endereço e recarregue a página.': 'ব্রাউজার এই সাইটের বিজ্ঞপ্তি আটকে দিয়েছে। ঠিকানার পাশের তালা থেকে অনুমতি দাও আর পাতাটা আবার লোড করো।',
  'O selo aparece aqui quando o primeiro marco cair. Até lá ele fica guardado — e chegar nele é justamente o que ele vai significar.': 'প্রথম মাইলফলক ছুঁলে সিলটা এখানে দেখা দেবে। ততদিন তোলা থাকে — আর সেখানে পৌঁছানোই তো তার মানে হবে।',
  'Outros aparelhos': 'অন্য যন্ত্র',
  'Ouvir': 'শোনো',
  'Pacote do Syden': 'Syden-এর প্যাকেজ',
  'Parar teste': 'পরীক্ষা থামাও',
  'por {quem}': '{quem}-এর পাঠানো',
  'Processamento de voz': 'গলার প্রক্রিয়াকরণ',
  'Quem tiver este código entra na comunidade: pela tela de cadastro, se ainda não tem conta, ou pelo botão de entrar, se já usa o Syden.': 'এই কোড যার কাছে আছে সে কমিউনিটিতে ঢুকে পড়ে: অ্যাকাউন্ট না থাকলে সাইন-আপের পাতা দিয়ে, আর আগে থেকে Syden ব্যবহার করলে যোগ দেওয়ার বোতাম দিয়ে।',
  'Reduz barulhos de fundo, como teclado, ventilador e trânsito.': 'কিবোর্ড, ফ্যান আর রাস্তার মতো পেছনের আওয়াজ কমায়।',
  'Remover membro': 'সদস্য সরাও',
