  'Sair de {comunidade}? As suas mensagens continuam lá para quem ficou.': '{comunidade} ছাড়বে? যারা থাকছে তাদের জন্য তোমার বার্তা ওখানেই থাকবে।',
  'Sair dos outros aparelhos': 'অন্য যন্ত্রগুলো থেকে বেরিয়ে যাও',
  'Salvando…': 'রাখা হচ্ছে…',
  'Salvar nova senha': 'নতুন পাসওয়ার্ড রাখো',
  'Salvar o e-mail': 'ইমেলটা রাখো',
  'Salvar selo': 'সিল রাখো',
  'Selo da comunidade': 'কমিউনিটির সিল',
  'Senha alterada. Os outros aparelhos foram desconectados.': 'পাসওয়ার্ড বদলেছে। অন্য যন্ত্রগুলো বের করে দেওয়া হয়েছে।',
  'Senha definida. Agora dá para entrar com nome e senha também.': 'পাসওয়ার্ড ঠিক হয়েছে। এখন নাম আর পাসওয়ার্ড দিয়েও ঢুকতে পারো।',
  'Serve para recuperar a senha e para avisar você se algo acontecer com o Syden. Sem e-mail, uma senha esquecida não tem volta.': 'এটা পাসওয়ার্ড ফিরে পেতে কাজে লাগে, আর Syden-এর কিছু হলে তোমাকে জানাতে। ইমেল না থাকলে ভুলে যাওয়া পাসওয়ার্ডের আর ফেরার পথ নেই।',
  'Sons da comunidade': 'কমিউনিটির শব্দ',
  'Sons de aviso': 'বিজ্ঞপ্তির শব্দ',
  'Supressão de ruído': 'আওয়াজ দমন',
  'Teclas de atalho': 'শর্টকাট বোতাম',
  'Testar microfone': 'মাইক পরীক্ষা করো',
  'Tirar o selo': 'সিলটা খুলে দাও',
  'Toca um som quando alguém entra ou sai da sua sala, quando alguém começa a compartilhar a tela e quando você silencia ou ensurdece.': 'কেউ তোমার ঘরে ঢুকলে বা বেরোলে, কেউ পর্দা ভাগ করা শুরু করলে, আর তুমি নিজেকে চুপ বা বধির করলে একটা শব্দ বাজে।',
  'Tocando…': 'বাজছে…',
  'Todo mundo desta comunidade pode usar estes emojis escrevendo {exemplo} ou pelo botão de emoji do chat. Sem assinatura: está tudo liberado.': 'এই কমিউনিটির সবাই {exemplo} লিখে বা আড্ডার ইমোজি বোতাম দিয়ে এই ইমোজিগুলো ব্যবহার করতে পারে। কোনো চাঁদা নেই: সব খোলা।',
  'Traz de volta os emojis que vêm com o Syden. O que vocês enviaram continua como está, e nada vira cópia repetida.': 'Syden-এর সঙ্গে আসা ইমোজিগুলো ফিরিয়ে আনে। তোমরা যা পাঠিয়েছ তা যেমন আছে তেমনই থাকে, আর কিছুই দ্বিতীয়বার নকল হয় না।',
  'Trocar áudio': 'অডিও বদলাও',
  'Trocar avatar': 'অবতার বদলাও',
  'Ou escolha um coelho': 'অথবা একটা খরগোশ বেছে নাও',
  'Usar este coelho': 'এই খরগোশটি ব্যবহার করো',
  'Trocar imagem': 'ছবি বদলাও',
  'Trocar o e-mail': 'ইমেল বদলাও',
  'Trocar senha': 'পাসওয়ার্ড বদলাও',
  'Veja se o microfone está captando a sua voz.': 'দেখো মাইক তোমার গলা ধরছে কি না।',
  'Você ainda não tem nenhuma. Elas chegam como presente ou como recompensa — por exemplo, quando uma ideia sua entra no Syden.': 'তোমার এখনো একটাও নেই। এগুলো উপহার বা পুরস্কার হয়ে আসে — যেমন, তোমার কোনো ভাবনা Syden-এ ঢুকলে।',
  'Você entrou por um serviço de fora e ainda não tem senha nesta conta. Defina uma aqui: passa a valer como segundo jeito de entrar, e é o que permite desligar aquele serviço depois.': 'তুমি বাইরের একটা সেবা দিয়ে ঢুকেছ আর এই অ্যাকাউন্টে এখনো পাসওয়ার্ড নেই। এখানে একটা ঠিক করে নাও: এটা ঢোকার দ্বিতীয় পথ হয়ে যায়, আর এটাই পরে ওই সেবাটা খুলে ফেলতে দেয়।',
  'Você perde o acesso aos canais desta comunidade. Para voltar, vai precisar de um convite novo.': 'এই কমিউনিটির চ্যানেলগুলোয় তোমার ঢোকা বন্ধ হয়ে যাবে। ফিরতে হলে নতুন নিমন্ত্রণ লাগবে।',
  'ZECA': 'রাজু',
  '{email} — ainda não confirmado': '{email} — এখনো নিশ্চিত হয়নি',
  '{email} — confirmado': '{email} — নিশ্চিত হয়েছে',
  'Clique para escolher quais aparecem no seu perfil (até {limite}).': 'তোমার প্রোফাইলে কোনগুলো দেখা যাবে তা বেছে নিতে ক্লিক করো ({limite} পর্যন্ত)।',
  'Pessoas bloqueadas': 'আটকানো লোকেরা',
  'Quem está aqui não vê as suas mensagens nem você as dele, não consegue abrir conversa privada com você e não pode te mandar pedido de amizade.': 'এখানে যারা আছে তারা তোমার বার্তা দেখে না, তুমিও তাদেরটা দেখো না; তারা তোমার সঙ্গে ব্যক্তিগত আলাপ খুলতে পারে না আর তোমাকে বন্ধুত্বের অনুরোধও পাঠাতে পারে না।',
