  'Casa cheia': 'ঘর ভরা',
  'conversa em 10 dias diferentes': '১০টি আলাদা দিনে কথাবার্তা',
  'Não para nunca': 'কখনো থামে না',
  'Nenhum pacote ainda. Monte o primeiro com imagens suas, ou publique os emojis que esta comunidade já tem.': 'এখনো কোনো প্যাকেজ নেই। প্রথমটা তোমার নিজের ছবি দিয়ে বানাও, বা এই কমিউনিটির কাছে যে ইমোজিগুলো আছে সেগুলো প্রকাশ করো।',
  'Os marcos abaixo foram escolhidos para não haver como alcançá-los sozinho — todos precisam de mais de uma pessoa, ao longo do tempo.': 'নিচের মাইলফলকগুলো এমনভাবে বাছা হয়েছে যাতে একা পৌঁছানোর কোনো উপায় না থাকে — প্রতিটার জন্য একের বেশি মানুষ লাগে, আর সময় লাগে।',
  'Progresso de {marco}': '{marco}-এর অগ্রগতি',
  'Quatro caracteres, um ícone e uma cor que aparecem ao lado do nome de quem é daqui.': 'চারটি অক্ষর, একটা আইকন আর একটা রং, যা এখানকার সবার নামের পাশে দেখা যায়।',
  'Só quem administra pode instalar ou tirar.': 'শুধু অ্যাডমিনরাই বসাতে বা খুলতে পারে।',
  'Turma formada': 'দল গড়ে উঠেছে',
  'Um pacote instalado entra para toda a comunidade: os emojis dele passam a valer nas mensagens de todo mundo.': 'বসানো প্যাকেজ পুরো কমিউনিটির হয়ে যায়: তার ইমোজিগুলো সবার বার্তায় চলতে শুরু করে।',
  'Vozes juntas': 'কণ্ঠ একসাথে',
  'Anil': 'নীল',
  'Apaga a sua conta, as suas mensagens e o seu avatar. Os canais, emojis e sons que você criou continuam no servidor para os outros.': 'তোমার অ্যাকাউন্ট, তোমার বার্তা আর তোমার অবতার মুছে দেয়। তুমি যে চ্যানেল, ইমোজি আর শব্দ বানিয়েছ, সেগুলো অন্যদের জন্য সার্ভারে থাকে।',
