  'Corta a voz em batidas, como as pás girando.': 'গলাটা থাপে থাপে কেটে দেয়, ঘোরা পাখার মতো।',
  'Desligado, a transmissão de quem está na sala aparece como convite e só começa a ser baixada quando você clica em Assistir. Isso poupa internet e processador — principalmente em sala cheia.': 'বন্ধ থাকলে ঘরের কারও সম্প্রচার শুধু একটা নিমন্ত্রণ হিসেবে দেখায়, আর তুমি দেখো-তে ক্লিক করলে তবেই নামতে শুরু করে। এতে ইন্টারনেট আর প্রসেসর বাঁচে — ভরা ঘরে তো বিশেষ করে।',
  'Durante uma chamada, esse botão toca estes sons para todos na sala. Instale pacotes prontos ou envie os seus; o que é seu favorito fica na frente do painel.': 'কথা বলার সময় ওই বোতামটা এই শব্দগুলো ঘরের সবাইকে শোনায়। তৈরি প্যাকেজ বসাও বা নিজেরটা পাঠাও; তোমার পছন্দেরটা প্যানেলের সামনে থাকে।',
