  'O desenho precisa de pelo menos 2 pessoas na sala.': 'আঁকো আর আন্দাজ করো খেলতে রুমে অন্তত 2 জন লাগে।',
  'Agora não é hora de escolher.': 'এখন বাছাইয়ের সময় নয়।',
  'Quem escolhe a palavra é quem vai desenhar.': 'যে আঁকবে, শব্দটা সে-ই বেছে নেয়।',
  'Escolha uma das três palavras.': 'তিনটি শব্দের একটি বেছে নাও।',
