  'Só quem desenha mexe no desenho.': 'শুধু যে আঁকছে, সে-ই ছবিতে হাত দিতে পারে।',
  'Cargos automáticos': 'স্বয়ংক্রিয় ভূমিকা',
  'Crie os cargos da comunidade primeiro, em Membros. Depois volte aqui para entregá-los sozinhos.': 'আগে সদস্য অংশে কমিউনিটির ভূমিকাগুলো তৈরি করো। তারপর এখানে ফিরে এসো, যাতে সেগুলো নিজে থেকেই দেওয়া হয়।',
  'Cargo de quem entra': 'নতুনদের ভূমিকা',
  'Toda pessoa nova recebe estes cargos ao entrar na comunidade.': 'কমিউনিটিতে ঢুকলেই প্রত্যেক নতুন মানুষ এই ভূমিকাগুলো পায়।',
  'Cargos por reação': 'প্রতিক্রিয়া দিয়ে ভূমিকা',
  'O Syden publica uma mensagem no canal com um emoji para cada cargo. Quem reage ganha o cargo; quem tira a reação, perde.': 'Syden চ্যানেলে একটা বার্তা পোস্ট করে, প্রতিটি ভূমিকার জন্য একটা করে ইমোজি দিয়ে। যে প্রতিক্রিয়া দেয় সে ভূমিকাটা পায়; যে প্রতিক্রিয়া সরিয়ে নেয়, সে হারায়।',
  'Apagar o painel': 'প্যানেল মুছে ফেলো',
  'Escolha os seus cargos reagindo aqui embaixo!': 'নিচে প্রতিক্রিয়া দিয়ে তোমার ভূমিকা বেছে নাও!',
  'Texto do painel': 'প্যানেলের লেখা',
