  'Publicar o painel': 'প্যানেল পোস্ট করো',
  'Quais jogos a turma joga, com quantas pessoas e quantas partidas vão até o fim. Só contagem: respostas e desenhos não são guardados. Conta a partir de 12/10/2026.': 'দলটা কোন কোন খেলা খেলে, কতজন মিলে, আর কতগুলো ম্যাচ শেষ পর্যন্ত যায়। শুধু গণনা: উত্তর আর আঁকা ছবি রাখা হয় না। গণনা শুরু 12/10/2026 থেকে।',
  '{n} dias': '{n} দিন',
