  'A música': 'গান',
  'O emoji': 'ইমোজি',
  'O arquivo': 'ফাইল',
  '{tipo} «{item}» ({onde}) saiu do Syden porque {quem} disse ter os direitos. Se você tinha autorização para publicar, responda aqui contando: a sua resposta vai ser levada em conta. Enquanto isso não ficar claro, fica fora. Os termos explicam como funciona, na seção 4: https://syden.chat/termos.html#direito-autoral': '{tipo} «{item}» ({onde}) Syden থেকে সরিয়ে নেওয়া হয়েছে, কারণ {quem} জানিয়েছেন যে এর অধিকার তাঁদের। যদি তোমার প্রকাশ করার অনুমতি থেকে থাকে, এখানে উত্তর দিয়ে জানাও: তোমার উত্তর বিবেচনা করা হবে। বিষয়টা পরিষ্কার না হওয়া পর্যন্ত এটা সরানোই থাকবে। কীভাবে কাজ করে, তা শর্তাবলির ৪ নম্বর অংশে বলা আছে: https://syden.chat/termos.html#direito-autoral',
  '«{nome}» saiu.': '«{nome}» সরিয়ে নেওয়া হয়েছে।',
  'Saíram junto {n} cópia(s) do mesmo arquivo.': 'একই ফাইলের যে কপিগুলো সঙ্গে সরানো হলো: {n}',
  'Quem subiu recebeu o aviso numa conversa com você.': 'যে আপলোড করেছিল, সে তোমার সঙ্গে একটা কথোপকথনে নোটিশ পেয়েছে।',
  'Não havia a quem avisar.': 'জানানোর মতো কেউ ছিল না।',
  'É a retirada número {n} desta pessoa.': 'এটা এই মানুষটার {n} নম্বর সরানো।',
  'Direito autoral': 'কপিরাইট',
  'Quem tem o direito escreve para direitos@syden.chat dizendo o que é e onde está. Procure pelo nome, retire, e quem subiu recebe o aviso numa conversa com você, onde pode contestar.': 'যার অধিকার আছে, সে direitos@syden.chat-এ লিখে জানায় জিনিসটা কী আর কোথায় আছে। নাম দিয়ে খোঁজো, সরিয়ে দাও, আর যে আপলোড করেছিল সে তোমার সঙ্গে একটা কথোপকথনে নোটিশ পায়, যেখানে সে আপত্তি জানাতে পারে।',
  'Nome do som, da música, do emoji ou do arquivo': 'সাউন্ড, গান, ইমোজি বা ফাইলের নাম',
  'Procurar conteúdo': 'কনটেন্ট খোঁজো',
  'Procurar': 'খোঁজো',
