  '{n} retirada(s) antes': 'আগে সরানো হয়েছে: {n}',
  'Quem reclamou (nome e e-mail)': 'কে অভিযোগ করেছে (নাম ও ইমেইল)',
  'Quem reclamou': 'কে অভিযোগ করেছে',
