  'Retirar e avisar': 'সরাও ও জানাও',
  'Retirar': 'সরাও',
  'Retiradas feitas': 'যা সরানো হয়েছে',
  'Nenhuma retirada até agora.': 'এখনও কিছু সরানো হয়নি।',
  'Reclamação de {quem}. Quem retirou: {por}.': 'অভিযোগ: {quem}। সরিয়েছে: {por}।',
  'Tickets': 'টিকিট',
  'Quem precisa falar com a administração abre um ticket no início da comunidade, com um assunto. Ele vira uma conversa privada em grupo entre essa pessoa e quem administra, e aparece na lista de conversas de vocês.': 'যার অ্যাডমিনদের সঙ্গে কথা বলা দরকার, সে কমিউনিটির শুরুর পাতা থেকে একটা বিষয় দিয়ে টিকিট খোলে। সেটা ওই মানুষটা আর অ্যাডমিনদের মধ্যে একটা ব্যক্তিগত দলগত কথোপকথন হয়ে যায়, আর তোমাদের কথোপকথনের তালিকায় দেখা যায়।',
  'Deixar os membros abrirem tickets': 'সদস্যদের টিকিট খুলতে দাও',
