  'Abrir ticket': 'টিকিট খোলো',
  'Só quem administra a comunidade liga os tickets.': 'শুধু কমিউনিটির অ্যাডমিনরাই টিকিট চালু করতে পারে।',
  'Esta comunidade não usa tickets.': 'এই কমিউনিটি টিকিট ব্যবহার করে না।',
  'Diga em poucas palavras qual é o assunto.': 'অল্প কথায় বলো বিষয়টা কী।',
  'Ainda não há quem atenda os tickets nesta comunidade.': 'এই কমিউনিটিতে এখনও টিকিটের উত্তর দেওয়ার কেউ নেই।',
  'Ticket não encontrado.': 'টিকিট পাওয়া যায়নি।',
  'Só quem abriu o ticket ou quem administra pode encerrá-lo.': 'শুধু যে টিকিট খুলেছে সে বা অ্যাডমিনরা এটা বন্ধ করতে পারে।',
  'Só quem administra a comunidade mexe nos cargos automáticos.': 'শুধু কমিউনিটির অ্যাডমিনরাই স্বয়ংক্রিয় ভূমিকা বদলাতে পারে।',
  'Escolha um canal de texto da comunidade.': 'কমিউনিটির একটা লেখার চ্যানেল বেছে নাও।',
  'Um dos emojis não vale.': 'একটা ইমোজি বৈধ নয়।',
  'Um dos cargos não existe.': 'একটা ভূমিকার অস্তিত্ব নেই।',
  'Cada emoji só pode dar um cargo.': 'প্রতিটি ইমোজি শুধু একটা ভূমিকাই দিতে পারে।',
  'Painel não encontrado.': 'প্যানেল পাওয়া যায়নি।',
  'E-mail confirmado. Agora dá para recuperar a sua senha por ele.': 'ইমেইল নিশ্চিত হয়েছে। এখন এটা দিয়ে তোমার পাসওয়ার্ড ফিরে পাওয়া যাবে।',
  'A resposta veio sem a sua conta. Tente de novo.': 'উত্তরে তোমার অ্যাকাউন্ট আসেনি। আবার চেষ্টা করো।',
  'Conta do {provedor} ligada. Agora dá para entrar por ela.': '{provedor} অ্যাকাউন্ট যুক্ত হয়েছে। এখন এটা দিয়ে ঢোকা যাবে।',
