  'Obrigado de verdade. Fique de olho nas novidades da tela inicial para ver a sua ideia funcionando — e a medalha de contribuição já está no seu perfil.': 'সত্যিই ধন্যবাদ। হোম স্ক্রিনের নতুন খবরে চোখ রাখো, তোমার ভাবনাকে কাজ করতে দেখবে — আর অবদানের পদক এর মধ্যেই তোমার প্রোফাইলে আছে।',
