  'nos últimos 7 dias: {tempo}': 'গত ৭ দিনে: {tempo}',
  'O limite combinado com o seu responsável é de {n} minutos por dia. Amanhã, o Syden abre de novo.': 'তোমার অভিভাবকের সঙ্গে ঠিক করা সীমা দিনে {n} মিনিট। কাল Syden আবার খুলবে।',
  'O motivo (a pessoa vai ler)': 'কারণ (মানুষটি এটা পড়বে)',
  'O seu recurso foi recebido em {quando}. Quem cuida do Syden vai ler e responder.': 'তোমার আপিল {quando}-এ পাওয়া গেছে। Syden যাঁরা দেখাশোনা করেন তাঁরা পড়ে উত্তর দেবেন।',
  'O seu responsável': 'তোমার অভিভাবক',
  'O seu tempo de hoje acabou': 'আজকের সময় শেষ',
  'O Syden é para quem tem 13 anos ou mais.': 'Syden ১৩ বছর বা তার বেশি বয়সীদের জন্য।',
  'O Syden é para quem tem 13 anos ou mais. Ninguém vê a sua data.': 'Syden ১৩ বছর বা তার বেশি বয়সীদের জন্য। তোমার তারিখ কেউ দেখে না।',
  'O Syden passou a pedir a idade de todo mundo, para proteger quem tem menos de 18 anos (a lei do ECA Digital). Ninguém vê a sua data: só a faixa de idade é usada.': 'Syden এখন সবার বয়স জানতে চায়, ১৮ বছরের কম বয়সীদের সুরক্ষার জন্য (ECA Digital আইন)। তোমার তারিখ কেউ দেখে না: শুধু বয়সের সীমা ব্যবহার হয়।',
  'Para quem foi comunicado e o protocolo (ex.: SaferNet 123)': 'কাকে জানানো হয়েছে এবং প্রোটোকল (যেমন: SaferNet 123)',
  'Por segurança, a prévia das transmissões fica fechada para menores de idade.': 'নিরাপত্তার জন্য, নাবালকদের জন্য স্ট্রিমের প্রিভিউ বন্ধ থাকে।',
  'Por segurança, menores de idade conversam no particular só com amigos.': 'নিরাপত্তার জন্য, নাবালকরা ব্যক্তিগতভাবে শুধু বন্ধুদের সঙ্গে কথা বলে।',
  'Qual é a sua data de nascimento?': 'তোমার জন্মতারিখ কত?',
  'Quem muda estas regras é o seu responsável.': 'এই নিয়মগুলো বদলান তোমার অভিভাবক।',
  'Quem tem de 13 a 15 anos usa o Syden com a conta ligada à de um pai, mãe ou responsável. É a lei (ECA Digital), e é para a sua segurança.': '১৩ থেকে ১৫ বছর বয়সীরা Syden ব্যবহার করে বাবা, মা বা অভিভাবকের অ্যাকাউন্টের সঙ্গে যুক্ত অ্যাকাউন্টে। এটা আইন (ECA Digital), আর তোমার নিরাপত্তার জন্য।',
  'Quem tem menos de 18 anos usa o Syden com proteções a mais, e de 13 a 15 anos com a conta ligada à de um responsável (a lei do ECA Digital).': '১৮ বছরের কম বয়সীরা Syden ব্যবহার করে বাড়তি সুরক্ষা নিয়ে, আর ১৩ থেকে ১৫ বছর বয়সীদের অ্যাকাউন্ট একজন অভিভাবকের অ্যাকাউন্টের সঙ্গে যুক্ত থাকে (ECA Digital আইন)।',
