  'Setas para dirigir, Espaço para derrapar, E para usar o item.': 'চালাতে তীর চিহ্ন, ড্রিফট করতে স্পেস, আইটেম ব্যবহার করতে E।',
  'Copa da turma': 'দলের কাপ',
  'Copas da Cenoura que a turma correu até o fim, na Corrida dos coelhos.': 'খরগোশের দৌড়ে দল শেষ পর্যন্ত যে গাজর কাপগুলো দৌড়েছে।',
  'Bosque': 'বন',
  'Cânion': 'গিরিখাত',
  'Copa do Repolho': 'বাঁধাকপি কাপ',
  'Festa dos coelhos': 'খরগোশের পার্টি',
  'Cinco rodadas de jogos rápidos, cada um na própria tela: reflexo, pontaria, memória e olho. Quem for melhor em cada rodada ganha mais pontos.': 'পাঁচ রাউন্ড দ্রুত খেলা, প্রত্যেকে নিজের স্ক্রিনে: রিফ্লেক্স, নিশানা, স্মৃতি আর চোখ। প্রতি রাউন্ডে যে সবচেয়ে ভালো করে, সে বেশি পয়েন্ট পায়।',
  'Saque rápido': 'দ্রুত গুলি',
  'Espere o sinal e aperte o mais rápido que puder. Antes do sinal, está fora.': 'সংকেতের জন্য অপেক্ষা করো, তারপর যত দ্রুত পারো চাপো। সংকেতের আগে চাপলে তুমি বাদ।',
  'Medidor de força': 'শক্তি মাপক',
  'Pare a barra o mais perto possível de 100%.': 'বারটা যতটা সম্ভব 100%-এর কাছে থামাও।',
  'Parar o relógio': 'ঘড়ি থামাও',
  'Pare o relógio em 10 segundos exatos. Os números somem depois de 3.': 'ঘড়িটা ঠিক 10 সেকেন্ডে থামাও। 3-এর পরে সংখ্যাগুলো মিলিয়ে যায়।',
  'Jogo dos copos': 'কাপের খেলা',
  'Veja onde fica a cenoura e siga o copo. Acertar mais rápido vale mais.': 'গাজরটা কোথায় আছে দেখো আর কাপটা অনুসরণ করো। যত দ্রুত ঠিক বলবে, তত বেশি পয়েন্ট।',
  'Siga o coelho': 'খরগোশকে অনুসরণ করো',
  'Repita as setas na ordem. A cada acerto, vem mais uma.': 'তীরগুলো ক্রম অনুযায়ী আবার করো। প্রতিবার ঠিক হলে আরও একটা আসে।',
  'Tiro ao alvo': 'লক্ষ্যভেদ',
  'Acerte os alvos que aparecerem. Cada um vale um ponto.': 'যে লক্ষ্যগুলো দেখা দেয় সেগুলোতে লাগাও। প্রতিটার মূল্য এক পয়েন্ট।',
  'Cedo demais!': 'খুব তাড়াতাড়ি!',
  'Não valeu': 'গণনা হয়নি',
  'Sem resposta': 'কোনো উত্তর নেই',
  'Errou': 'ভুল',
  'Nenhum troféu ainda. Fique no pódio de um jogo na sala, com a turma.': 'এখনও কোনো ট্রফি নেই। ঘরে দলের সঙ্গে একটা খেলায় পোডিয়ামে ওঠো।',
  'Briga na horta': 'বাগানে মারামারি',
  'Horta em cascata': 'বাগানের ঝরনা',
  'Prado': 'তৃণভূমি',
