  'Leve a nuvem até o canteiro com sede.': 'মেঘটাকে তৃষ্ণার্ত বাগানের কাছে নিয়ে যাও।',
  'Leve as três tábuas até a ponte. Cuidado com as pedras que afundam!': 'তিনটে তক্তা সেতু পর্যন্ত নিয়ে যাও। যে পাথর ডোবে, তা থেকে সাবধান!',
  'Mangue': 'ম্যানগ্রোভ',
  'Moletom': 'হুডি',
  'Na banheira': 'বাথটাবে',
  'Na Caça às pragas, o que serve de munição?': 'বাগানের পোকা শিকারে গুলি হিসেবে কী ব্যবহার হয়?',
  'Na cama': 'খাটে',
  'Na Corrida dos coelhos, o kart do mascote parece o quê?': 'খরগোশের দৌড়ে মাসকটের কার্টটা দেখতে কেমন?',
  'Na sua vez, vire uma carta ou guarde as cenouras. A raposa leva tudo!': 'নিজের পালায় একটা তাস উল্টাও বা গাজর তুলে রাখো। শিয়াল সব নিয়ে যায়!',
  'Nenhum amigo subiu esta torre ainda.': 'এখনো কোনো বন্ধু এই মিনারে চড়েনি।',
  'Ninguém': 'কেউ না',
  'No ar': 'আকাশে',
  'No quarto, o que abre os Mini-games?': 'ঘরে কোনটা মিনি-গেম খোলে?',
  'No quarto, o que leva às salas de voz?': 'ঘরে কোনটা ভয়েস রুমে নিয়ে যায়?',
  'No quarto, o que troca o dia pela noite?': 'ঘরে কোনটা দিন-রাত বদলায়?',
  'No quarto, onde o coelho dorme quando a pessoa está ausente?': 'ঘরে, মানুষটা না থাকলে খরগোশ কোথায় ঘুমায়?',
  'No salão da comunidade, o que abre os Mini-games?': 'কমিউনিটির হলঘরে কোনটা মিনি-গেম খোলে?',
  'No salão, a TV leva aonde?': 'হলঘরে টিভি কোথায় নিয়ে যায়?',
