  'O abajur': 'ল্যাম্প',
  'O balcão': 'কাউন্টার',
  'O barco desliza: tire o pé antes da curva. As argolas laranja dão um empurrão.': 'নৌকা পিছলায়: বাঁকের আগে গতি ছাড়ো। কমলা আংটিগুলো ধাক্কা দেয়।',
