  'Ouça, repita a batida no mesmo ritmo e acrescente uma no fim.': 'শোনো, একই তালে তালটা আবার বাজাও আর শেষে একটা যোগ করো।',
  'Paiol': 'শস্যের গোলা',
  'Pare cada faixa com o retrato no lugar, de cima para baixo.': 'উপর থেকে নিচে, ছবি ঠিক জায়গায় এলে প্রতিটা সারি থামাও।',
  'Pare os três rolos na mesma figura. Cada trinca vale um ponto.': 'তিনটে রিল একই ছবিতে থামাও। প্রতিটা তিনে-মিল এক পয়েন্ট।',
  'Pedras': 'পাথর',
  'Pegue a galinha': 'মুরগি ধরো',
  'Pegue as cenouras no gelo e fuja dos repolhos.': 'বরফের উপর গাজর কুড়োও আর বাঁধাকপি এড়াও।',
  'Pegue uma cenoura dourada e leve até a porteira. Falta uma: empurre quem estiver carregando!': 'একটা সোনালি গাজর নিয়ে ফটক পর্যন্ত যাও। একটা কম: যে বইছে তাকে ঠেলো!',
  'Pilotar (para trás, freia e dá ré)': 'চালানো (পেছনে চাপলে ব্রেক আর পিছু হটা)',
  'Plantar': 'লাগানো',
