  'Praga na toca': 'গর্তে পোকা',
  'Prenda a mira, depois a força. Quem parar mais perto da toca ganha.': 'আগে নিশানা ঠিক করো, তারপর জোর। যে গর্তের সবচেয়ে কাছে থামে, সে জেতে।',
  'Preta': 'কালো',
  'Pronta': 'তৈরি',
  'Pula o ponteiro': 'কাঁটার উপর লাফ',
  'Pule do balanço para cair numa folha. A mais longe vale mais.': 'দোলনা থেকে লাফিয়ে একটা পাতায় নামো। যত দূরে, তত বেশি পয়েন্ট।',
  'Pule quando o ponteiro passar. Ele fica cada vez mais rápido.': 'কাঁটা পেরোনোর সময় লাফাও। সেটা ক্রমশ দ্রুত হয়।',
  'Pulo do balanço': 'দোলনা থেকে লাফ',
  'Qual destes bichos é uma praga da horta?': 'এদের মধ্যে কোন প্রাণী বাগানের পোকা?',
  'Qual destes cresce debaixo da terra?': 'এদের মধ্যে কোনটা মাটির নিচে জন্মায়?',
  'Qual destes é o mais pesado?': 'এদের মধ্যে কোনটা সবচেয়ে ভারী?',
  'Qual destes é uma ferramenta da horta?': 'এদের মধ্যে কোনটা বাগানের যন্ত্র?',
  'Qual destes é uma fruta vermelha?': 'এদের মধ্যে কোনটা লাল ফল?',
