  'Que bicho é o mascote do Syden?': 'Syden-এর মাসকট কোন প্রাণী?',
  'Quem ajuda as flores a virar frutos?': 'ফুলকে ফল হতে কে সাহায্য করে?',
  'Quem está atrás da turma?': 'ভিড়ের পেছনে কে?',
  'Quem está em qual toca?': 'কে কোন গর্তে?',
  'Quem está no remo manda ondas; quem está na jangada pula na hora!': 'দাঁড় যার হাতে সে ঢেউ পাঠায়; ভেলায় যে, সে ঠিক সময়ে লাফায়!',
  'Quem fica atrás do balcão do salão?': 'হলঘরের কাউন্টারের পেছনে কে থাকে?',
  'Quiz relâmpago': 'বিদ্যুৎ কুইজ',
  'Rebata quando o rabanete chegar à base. Bem na hora, vai mais longe.': 'মুলা বেসে এলে মারো। ঠিক সময়ে মারলে আরও দূরে যায়।',
