  'Sal e areia': 'নুন আর বালি',
  'Segure e solte: cenoura teleguiada': 'চেপে ধরে ছাড়ো: নিয়ন্ত্রিত গাজর',
  'Seis': 'ছয়',
  'Sem vidas: agora é torcer pela turma.': 'জীবন শেষ: এখন দলকে উৎসাহ দেওয়ার পালা।',
  'Siga os bichos de toca em toca. No fim, aponte onde está o do balão.': 'গর্ত থেকে গর্তে যাওয়া প্রাণীদের নজরে রাখো। শেষে দেখাও বেলুনওয়ালাটা কোথায়।',
  'Silo': 'সাইলো',
  'Solte o cipó quando ele estiver na faixa clara.': 'লতাটা হালকা ফালিতে থাকলে ছেড়ে দাও।',
  'Solte quando o nabo apontar para o campo. Girando mais rápido, vai mais longe.': 'শালগম মাঠের দিকে মুখ করলে ছেড়ে দাও। যত জোরে ঘোরে, তত দূরে যায়।',
  'Suba até o cata-vento. O que cai e os corvos levam de volta ao último andar.': 'বায়ুনির্দেশক পর্যন্ত চড়ো। পড়ন্ত জিনিস আর কাক শেষ পৌঁছানো তলায় ফিরিয়ে দেয়।',
  'Suba o celeiro por tábuas, fardos e vigas que se mexem até o cata-vento lá no alto, desviando das ferramentas que caem e dos corvos. No Solo, contra o relógio e os fantasmas dos amigos.': 'নড়তে থাকা তক্তা, খড়ের গাঁট আর কড়িকাঠ বেয়ে গোলাঘরের মাথায় বায়ুনির্দেশক পর্যন্ত চড়ো, পড়ন্ত যন্ত্রপাতি আর কাক এড়িয়ে। একা খেললে ঘড়ি আর বন্ধুদের ভূতের বিরুদ্ধে।',
  'Subida inválida.': 'অবৈধ চড়াই।',
