  'Coelhos a jato': 'জেট খরগোশ',
  'A corrida está andando.': 'দৌড় চলছে।',
  'Cidade à noite': 'রাতের শহর',
  'Órbita': 'কক্ষপথ',
  'Mar de nuvens': 'মেঘের সাগর',
  'Quantos adversários do computador?': 'কম্পিউটারের কতজন প্রতিপক্ষ?',
  'Balões': 'বেলুন',
  'Pegue as caixas e estoure os balões dos outros. Quem fica sem balão sai.': 'বাক্সগুলো তোলো আর অন্যদের বেলুন ফাটাও। যার বেলুন শেষ, সে বাদ।',
  'Sem balões: agora é assistir. ◀ ▶ trocam de quem.': 'বেলুন শেষ: এখন শুধু দেখা। ◀ ▶ দিয়ে বদলাও কাকে দেখবে।',
  'Você venceu!': 'জয়!',
  '{posicao}º lugar, entre {total}': '{total} জনের মধ্যে {posicao} নম্বর',
  'Balões que sobraram: {n}': 'বাকি বেলুন: {n}',
  'Balões estourados: {n}': 'ফাটানো বেলুন: {n}',
  'Freio de ar': 'এয়ার ব্রেক',
  'Turbo': 'টার্বো',
  'Pilotar': 'চালানো',
  'Turbo (da segunda volta em diante)': 'টার্বো (দ্বিতীয় ল্যাপ থেকে)',
  '{n} voltas': '{n} ল্যাপ',
  'A energia é a vida e o turbo: bater na borda gasta, a faixa cor-de-rosa recarrega.': 'শক্তিই প্রাণ, শক্তিই টার্বো: কিনারায় ধাক্কা খেলে খরচ হয়, গোলাপি ফালি আবার ভরে দেয়।',
  'A nave explodiu: a energia acabou.': 'যানটি বিস্ফোরিত হয়েছে: শক্তি শেষ।',
  'Posição: {posicao} de {total}': 'অবস্থান: {total}-এর মধ্যে {posicao}',
  'Escolher a pista': 'ট্র্যাক বেছে নাও',
  'Corrida de naves-cenoura numa pista suspensa, muito mais rápida que o kart. A energia é a vida e o turbo: bater na borda gasta, a faixa cor-de-rosa recarrega, e sair da pista é cair. No Solo, contra o relógio e os fantasmas dos amigos.': 'ঝুলন্ত ট্র্যাকে গাজর-যানের দৌড়, কার্টের চেয়ে অনেক দ্রুত। শক্তিই প্রাণ, শক্তিই টার্বো: কিনারায় ধাক্কা খেলে খরচ হয়, গোলাপি ফালি আবার ভরে দেয়, আর ট্র্যাক থেকে বেরোনো মানে পড়ে যাওয়া। একা খেললে ঘড়ি আর বন্ধুদের ভূতের বিরুদ্ধে।',
  'Os karts numa arena fechada, cada um com três balões. Pegue as caixas e use os itens para estourar os balões dos outros: quem fica sem balão sai, e ganha quem sobrar.': 'বন্ধ অ্যারেনায় কার্ট, প্রত্যেকটায় তিনটে বেলুন। বাক্সগুলো তোলো আর আইটেম দিয়ে অন্যদের বেলুন ফাটাও: যার বেলুন শেষ, সে বাদ, আর যে শেষ পর্যন্ত টিকে থাকে, সে জেতে।',
  'Esquadrilha da toca': 'গর্তের স্কোয়াড্রন',
  'Aviõezinhos de cenoura contra a praga da horta: desvie das sementes, pegue os reforços e derrube o espantalho mecânico no fim. A turma voa as mesmas ondas, e a esquadrilha soma os pontos.': 'গাজরের ছোট্ট বিমান বনাম বাগানের পোকা: বীজ এড়িয়ে চলো, শক্তি বাড়ানোর জিনিস নাও আর শেষে যান্ত্রিক কাকতাড়ুয়াকে নামিয়ে ফেলো। দল একই ঢেউয়ে ওড়ে, আর স্কোয়াড্রনের পয়েন্ট যোগ হয়।',
  'O espantalho caiu!': 'কাকতাড়ুয়া পড়ে গেছে!',
  'A praga venceu desta vez.': 'এবার পোকারা জিতে গেল।',
