  'Estratégia em tempo real contra o computador: colete comida, madeira e ouro, construa a vila, avance de era e treine o exército. Ganha quem derrubar o centro da vila do outro, ou construir a Maravilha e mantê-la de pé por 2 minutos.': 'কম্পিউটারের বিরুদ্ধে রিয়েল-টাইম কৌশল: খাবার, কাঠ আর সোনা জোগাড় করো, গ্রাম গড়ো, পরের যুগে যাও আর সেনা তৈরি করো। জেতে সে, যে অন্যজনের গ্রাম-কেন্দ্র ভেঙে ফেলে, বা বিস্ময় বানিয়ে 2 মিনিট দাঁড় করিয়ে রাখে।',
