  'Escolha um navio e toque no mar. Arraste para mudar de lugar.': 'একটা জাহাজ বেছে সমুদ্রে ছোঁও। জায়গা বদলাতে টানো।',
  'Sortear a frota': 'এলোমেলো নৌবহর',
