  'Ponha todos os navios antes.': 'আগে সব জাহাজ রাখো।',
  'Escolha um navio.': 'একটা জাহাজ বেছে নাও।',
  'O navio não cabe aí.': 'জাহাজটা ওখানে আঁটে না।',
  'Os navios não podem encostar um no outro.': 'জাহাজগুলো একে অপরকে ছুঁতে পারবে না।',
  'Minigolfe 3D': 'মিনি গলফ 3D',
  'Oito buracos em 3D, com rampas, castelo e moinho, todos jogando o mesmo ao mesmo tempo. Arraste para mirar e dar a força, e solte. Ganha quem somar menos tacadas.': '3D-তে আটটা গর্ত, র‍্যাম্প, দুর্গ আর বায়ুকল সহ, সবাই একই সময়ে একই গর্ত খেলে। নিশানা আর জোর ঠিক করতে টানো, তারপর ছেড়ে দাও। মোট সবচেয়ে কম শট যার, সে জেতে।',
  'Ver o buraco de cima': 'গর্তটা ওপর থেকে দেখো',
  'Fora da pista! Mais uma tacada.': 'পথের বাইরে! আরও একটা শট।',
  'Arraste para o lado para mirar e para baixo para a força, e solte. No teclado: as setas miram, e o Espaço segurado dá a força.': 'নিশানার জন্য পাশে আর জোরের জন্য নিচে টানো, তারপর ছেড়ে দাও। কিবোর্ডে: তীর চিহ্ন দিয়ে নিশানা, আর স্পেস চেপে রাখলে জোর বাড়ে।',
  'Futebol dos coelhos': 'খরগোশদের ফুটবল',
  'Futebol de campo pequeno, visto de cima. Encoste na bola para conduzir, segure Espaço para chutar mais forte e passe com X. Na sala, os times se completam com robôs.': 'ছোট মাঠের ফুটবল, ওপর থেকে দেখা। বল নিয়ে যেতে ছুঁয়ে দাও, জোরে শট নিতে স্পেস চেপে রাখো, আর X দিয়ে পাস দাও। রুমে দলগুলো রোবট দিয়ে পূর্ণ করা হয়।',
  'Quantos por time?': 'প্রতি দলে কতজন?',
