  'Caça às pragas da horta': 'বাগানের পোকা শিকার',
  'Corvos e gafanhotos atacam a horta. Mire e clique para acertar antes que fujam: a munição é contada, e cada onda vem mais rápida. Ganha quem fizer mais pontos.': 'কাক আর ফড়িং বাগানে হামলা করছে। পালানোর আগে নিশানা করে ক্লিক করো: গুলি গোনা, আর প্রতিটা ঢেউ আরও দ্রুত আসে। যে সবচেয়ে বেশি পয়েন্ট পায়, সে জেতে।',
  'Mire e clique nas pragas antes que fujam. Cada tiro gasta uma cenoura.': 'পালানোর আগে পোকাগুলোকে নিশানা করে ক্লিক করো। প্রতিটা গুলিতে একটা গাজর খরচ হয়।',
