  'Uma jogada não valeu.': 'একটা চাল গোনা হয়নি।',
  'Subir a pilha': 'স্তূপ তোলো',
  'Setas para mover, Espaço para trocar, X para subir a pilha.': 'নড়তে তীর চিহ্ন, বদলাতে স্পেস, স্তূপ তুলতে X।',
