  'Puxe a bola para trás e solte. No teclado: as setas miram, e o Espaço segurado dá a força.': 'বলটা পেছনে টেনে ছেড়ে দাও। কিবোর্ডে: তীর চিহ্ন দিয়ে নিশানা, আর স্পেস চেপে রাখলে জোর বাড়ে।',
