  'Para a direita': 'ডান দিকে',
  'Setas para correr, Espaço para pular (segure para ir mais alto).': 'দৌড়াতে তীর চিহ্ন, লাফাতে স্পেস (আরও উঁচুতে যেতে চেপে রাখো)।',
  'Nenhum amigo jogou esta fase ainda.': 'এখনো কোনো বন্ধু এই লেভেল খেলেনি।',
  'Chuva na horta: todo mundo ganha {n} cenouras.': 'বাগানে বৃষ্টি: সবাই {n}টা গাজর পায়।',
  '{nome} achou {n} cenouras escondidas.': '{nome} {n}টা লুকানো গাজর খুঁজে পেয়েছে।',
