  'Faltou gente: a partida acabou antes do fim, sem troféus.': 'লোক কম পড়েছে: খেলা শেষের আগেই থেমে গেছে, কোনো ট্রফি ছাড়া।',
  'Saiu antes do fim': 'শেষের আগে চলে গেছে',
