  '{nome} comprou a cenoura dourada!': '{nome} সোনার গাজর কিনেছে!',
  'Comprar a cenoura dourada por {preco} cenouras?': '{preco}টা গাজরে সোনার গাজর কিনবে?',
  'Comprar': 'কেনো',
  '{nome} chegou à cenoura dourada.': '{nome} সোনার গাজরে পৌঁছে গেছে।',
  'Quantas rodadas?': 'কত রাউন্ড?',
  'Os coelhos defendem a horta de raposas, corvos e um texugo. Andem juntos, batam em combo e cuidem uns dos outros: de 1 a 4 pessoas.': 'খরগোশেরা শিয়াল, কাক আর একটা ব্যাজারের হাত থেকে বাগান রক্ষা করে। একসঙ্গে এগোও, কম্বোতে মারো আর একে অপরের খেয়াল রাখো: 1 থেকে 4 জন।',
  'Pulo do coelho': 'খরগোশের লাফ',
  'Uma corrida de plataforma: correr, pular e não cair. Sozinho, contra o relógio e os fantasmas dos amigos; com a turma, ao vivo, numa fase ou nas três.': 'একটা প্ল্যাটফর্ম রেস: দৌড়াও, লাফাও আর পড়ে যেও না। একা, ঘড়ি আর বন্ধুদের ভূতের বিরুদ্ধে; দলের সঙ্গে, সরাসরি, একটা লেভেলে বা তিনটেতেই।',
  'Troque dois legumes vizinhos para juntar três ou mais iguais. A pilha sobe sem parar: não deixe chegar ao topo. Com a turma, as cadeias e os combos mandam caixotes para os outros.': 'পাশাপাশি দুটো সবজি বদলে তিন বা তার বেশি একই রকম মেলাও। স্তূপ থামে না, উঠতেই থাকে: চূড়ায় পৌঁছাতে দিও না। দলের সঙ্গে চেইন আর কম্বো অন্যদের কাছে বাক্স পাঠায়।',
  'Seis buracos de minigolfe, todos jogando o mesmo ao mesmo tempo. Puxe a bola para trás e solte para dar a tacada. Ganha quem somar menos tacadas.': 'মিনি গলফের ছয়টা হোল, সবাই একই সময়ে একই হোল খেলে। শট নিতে বলটা পেছনে টেনে ছেড়ে দাও। মোট সবচেয়ে কম শট যার, জয় তার।',
  'Cada um joga o dado na sua vez e anda pela horta. Junte cenouras para comprar a cenoura dourada, e depois de cada rodada a turma joga um microjogo. Ganha quem tiver mais cenouras douradas.': 'পালা করে ছক্কা ফেলে বাগানে এগোনো হয়। সোনার গাজর কিনতে গাজর জমাও, আর প্রতি রাউন্ডের পরে দল একটা মাইক্রোগেম খেলে। সবচেয়ে বেশি সোনার গাজর যার, জয় তার।',
  'Os pódios e as conquistas da turma': 'পোডিয়াম আর দলের অর্জন',
  'Visitar o quarto': 'ঘর দেখতে যাও',
  'Quem visita o seu quarto': 'তোমার ঘরে কে আসতে পারে',
  'Todo mundo': 'সবাই',
  'Seus amigos': 'তোমার বন্ধুরা',
  'Só quem você convidar': 'শুধু যাদের তুমি ডাকবে',
  'Qualquer conta pode entrar e ver os troféus em destaque.': 'যে কোনো অ্যাকাউন্ট ঢুকে বাছাই করা ট্রফিগুলো দেখতে পারে।',
  'Seus amigos podem entrar e ver os troféus em destaque.': 'তোমার বন্ধুরা ঢুকে বাছাই করা ট্রফিগুলো দেখতে পারে।',
  'Nem os amigos entram, só quem você marcar aqui.': 'বন্ধুরাও ঢুকতে পারে না, শুধু যাদের তুমি এখানে বেছে দেবে।',
  'Você ainda não tem amigos para convidar.': 'এখনও ডাকার মতো কোনো বন্ধু তোমার নেই।',
  'Tirar do destaque': 'বাছাই থেকে সরাও',
  'Pôr em destaque': 'বাছাই করো',
  'Cabem até {n} em destaque': 'সর্বোচ্চ {n}টি বাছাই করা যায়',
  'Troféus de {nome}': '{nome}-এর ট্রফি',
  'Em destaque': 'বাছাই করা',
  'Nada em destaque ainda.': 'এখনও কিছু বাছাই করা হয়নি।',
  'Escolha pela estrela o que fica em destaque. É o que quem visita o seu quarto vê.': 'তারা দিয়ে বেছে নাও কোনগুলো বাছাই থাকবে। তোমার ঘরে যারা আসে, তারা এটাই দেখে।',
