  'Fantasma não encontrado.': 'ভূত পাওয়া যায়নি।',
  'Esse troféu não é seu.': 'এই ট্রফি তোমার নয়।',
  'Convide alguém da sua lista de amigos.': 'তোমার বন্ধু তালিকা থেকে কাউকে আমন্ত্রণ জানাও।',
  'Antes dos 18, o quarto abre só para amigos e convidados.': '১৮ বছরের আগে ঘরটি শুধু বন্ধু ও আমন্ত্রিতদের জন্য খোলে।',
  'Escolha até 6 para o destaque.': 'বিশেষভাবে দেখাতে সর্বোচ্চ ৬টি বেছে নাও।',
  'Cabem até 100 convidados.': 'সর্বোচ্চ ১০০ জনকে আমন্ত্রণ করা যায়।',
  'Você saiu da sala, e a partida continuou sem você.': 'তুমি রুম ছেড়ে গেছ, আর খেলাটি তোমাকে ছাড়াই চলেছে।',
  'Menos de duas pessoas ficaram até o fim: desta vez, sem pódio.': 'দুজনের কম মানুষ শেষ পর্যন্ত ছিল: এবার কোনো পোডিয়াম নেই।',
  'Esta fase já tinha começado quando você abriu: você assiste.': 'তুমি খোলার আগেই এই লেভেলটি শুরু হয়ে গিয়েছিল: তুমি দেখছ।',
  'Não deu para abrir o quarto agora.': 'এখন ঘরটি খোলা গেল না।',
