  'Essa cidade não é de quem a troca diz.': 'বিনিময়ে যার বলা হয়েছে, এই শহর তার নয়।',
  'Venda os prédios do grupo antes de trocar.': 'বিনিময়ের আগে গ্রুপের দালানগুলো বিক্রি করো।',
