  'Para construir, é preciso ter todas as cidades do grupo.': 'বানাতে হলে গ্রুপের সব শহর তোমার থাকতে হবে।',
  'Resgate as cidades hipotecadas do grupo antes de construir.': 'বানানোর আগে গ্রুপের বন্ধক রাখা শহরগুলো ছাড়িয়ে নাও।',
  'Essa cidade já tem o máximo de prédios.': 'এই শহরে ইতিমধ্যে সর্বোচ্চ দালান আছে।',
