  'Sua quadrilha ganhou o festival junino: receba {valor}.': 'তোমার নাচের দল জুন উৎসবের প্রতিযোগিতা জিতেছে: {valor} নাও।',
  'Achou dinheiro no bolso da calça: receba {valor}.': 'প্যান্টের পকেটে টাকা পেয়েছ: {valor} নাও।',
  'Vendeu tudo na feira: receba {valor}.': 'মেলায় সব বিক্রি হয়ে গেছে: {valor} নাও।',
  'O carro quebrou na estrada: pague {valor}.': 'রাস্তায় গাড়ি নষ্ট হয়ে গেছে: {valor} দাও।',
  'Multa por parar na calçada: pague {valor}.': 'ফুটপাতে গাড়ি থামানোর জরিমানা: {valor} দাও।',
  'Volte para a Largada e receba o salário.': 'শুরুতে ফিরে যাও আর বেতন নাও।',
  'Pegou uma carona: avance 3 casas.': 'লিফট পেয়েছ: ৩ ঘর এগোও।',
  'Pegou o ônibus errado: volte 3 casas.': 'ভুল বাসে উঠেছ: ৩ ঘর পিছিয়ে যাও।',
  'A chuva fechou a estrada: vá para o Engarrafamento.': 'বৃষ্টিতে রাস্তা বন্ধ: যানজটে যাও।',
  'Reforma geral: pague {valor} por prédio.': 'সব মেরামত: প্রতিটি দালানের জন্য {valor} দাও।',
  'É o seu aniversário: cada um te dá {valor}.': 'আজ তোমার জন্মদিন: সবাই তোমাকে {valor} করে দেয়।',
  'Você pagou a festa: dê {valor} a cada um.': 'পার্টির খরচ তুমি দিয়েছ: প্রত্যেককে {valor} করে দাও।',
