  'Ande pelas capitais do Brasil, compre cidades e cobre aluguel de quem parar nelas. Com uma região inteira, dá para construir prédios. Troque, dispute nos leilões e não fique sem dinheiro.': 'ব্রাজিলের রাজধানীগুলো ঘুরে শহর কেনো, আর যে সেখানে থামে তার কাছ থেকে ভাড়া নাও। পুরো অঞ্চল হাতে থাকলে দালান বানানো যায়। বিনিময় করো, নিলামে লড়ো, আর টাকা ফুরিয়ে যেতে দিও না।',
