  'No app do Syden, o recorte funciona com qualquer fundo.': 'Syden অ্যাপে যেকোনো পটভূমি সরানো যায়।',
  'O recorte com o modelo falhou, e ficou o recorte simples.': 'মডেল দিয়ে সরানো ব্যর্থ হয়েছে, তাই সাধারণ পদ্ধতিতে সরানো হয়েছে।',
