  'Tirar figurinha': 'স্টিকার সরাও',
  'Crie figurinhas com as suas imagens, ou salve as que receber numa conversa.': 'নিজের ছবি দিয়ে স্টিকার বানাও, বা কথোপকথনে পাওয়া স্টিকার সংরক্ষণ করো।',
  'Dominó': 'ডমিনো',
  'Truco': 'ট্রুকো',
  'Damas': 'চেকার্স',
  'Batalha naval': 'ব্যাটলশিপ',
  'O dominó de sempre, de 2 a 4 pessoas (com 4, em duplas). Encaixe as pedras pelas pontas, e quem bater primeiro leva os pontos das mãos dos outros.': 'চিরচেনা ডমিনো, ২ থেকে ৪ জন (৪ জন হলে জুটিতে)। ঘুঁটি প্রান্ত মিলিয়ে বসাও, আর যে আগে শেষ করে সে বাকিদের হাতের পয়েন্ট নিয়ে নেয়।',
  'O truco paulista, com vira e manilha, em 2 ou em duplas de 4. Peça truco, aumente para seis, nove e doze, ou corra. Ganha quem fizer 12 pontos.': 'সাও পাওলোর ট্রুকো, ভিরা আর মানিলা সহ, ২ জনে বা ৪ জনের জুটিতে। ট্রুকো ডাকো, ছয়, নয় আর বারোতে বাড়াও, নয়তো পালাও। যে ১২ পয়েন্ট পায় সে জেতে।',
  'As damas brasileiras: comer é obrigatório, para a frente e para trás, e a dama anda a diagonal inteira. A sala assiste.': 'ব্রাজিলের চেকার্স: খাওয়া বাধ্যতামূলক, সামনে আর পেছনে, আর রাজা পুরো কোণাকুণি চলে। রুম দেখে।',
  'Cada um esconde a sua frota e atira no mar do outro. Acertou, atira de novo. Vence quem afundar a frota inteira primeiro. A sala assiste.': 'সবাই নিজের নৌবহর লুকিয়ে রাখে আর অন্যের সমুদ্রে গোলা ছোড়ে। লাগলে আবার ছোড়ো। যে আগে পুরো বহর ডোবায় সে জেতে। রুম দেখে।',
