  Torre: 'নৌকা',
  Bispo: 'গজ',
  'Cozinha da toca': 'গর্তের রান্নাঘর',
  'Pegue os ingredientes nos caixotes, pique na tábua, cozinhe no fogão e no forno sem queimar, monte no prato e entregue na janela. Todos recebem os mesmos pedidos: ganha quem entregar mais pratos em 3 minutos.': 'বাক্স থেকে উপকরণ নাও, বোর্ডে কাটো, না পুড়িয়ে চুলা আর ওভেনে রান্না করো, প্লেটে সাজিয়ে জানালায় দিয়ে দাও। সবাই একই অর্ডার পায়: ৩ মিনিটে যে সবচেয়ে বেশি প্লেট দেয় সে জেতে।',
  'Pegar ou largar': 'তোলা বা রাখা',
  'Este jogo precisa de gráficos 3D, que não abriram neste aparelho.': 'এই খেলার জন্য 3D গ্রাফিক্স লাগে, যা এই যন্ত্রে খোলেনি।',
  'Este prato não é o pedido.': 'এই প্লেট অর্ডার নয়।',
  Kickflip: 'Kickflip',
  Grab: 'Grab',
  Manual: 'Manual',
  'Rolê do coelho': 'খরগোশের চক্কর',
  'Um minuto na pista de skate. Pule, gire, faça grind nos corrimãos e emende as manobras num combo: cada manobra a mais multiplica os pontos, mas cair perde o combo inteiro.': 'স্কেট পার্কে এক মিনিট। লাফাও, ঘোরো, রেলিংয়ে গ্রাইন্ড করো আর কৌশলগুলো জুড়ে কম্বো বানাও: প্রতিটি বাড়তি কৌশল পয়েন্ট গুণ করে, কিন্তু পড়ে গেলে পুরো কম্বো হারাবে।',
  Pausar: 'বিরতি',
  'Caiu!': 'পড়ে গেছে!',
  'Melhor combo: {n}': 'সেরা কম্বো: {n}',
  'Trânsito da toca': 'গর্তের যানজট',
  'Um minuto para soltar os carros do cruzamento sem deixar que batam. Fila cheia também custa pontos.': 'চৌরাস্তা দিয়ে গাড়িগুলো ছাড়তে এক মিনিট, যেন ধাক্কা না লাগে। লাইন ভরে গেলেও পয়েন্ট কাটা যায়।',
  Liberar: 'ছাড়ো',
  'Carrinhos da toca': 'গর্তের খেলনা গাড়ি',
  'Uma pista de carrinhos de brinquedo com quatro faixas: o carro segue a faixa sozinho, e você só acelera. Acelerou demais na curva, ele sai voando e perde tempo. No Solo, contra o relógio, os fantasmas dos amigos e robôs.': 'চার লেনের খেলনা গাড়ির ট্র্যাক: গাড়ি নিজেই লেন ধরে চলে, আপনি শুধু গতি বাড়ান। বাঁকে বেশি গতি দিলে গাড়ি উড়ে ট্র্যাকের বাইরে চলে যায় আর সময় নষ্ট হয়। একা খেললে: ঘড়ি, বন্ধুদের ভূত আর রোবটদের বিরুদ্ধে।',
  'Acelerar': 'গতি বাড়ান',
